function heading(kicker,title,description,badge){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1><span class="terminal-chevron">&gt;</span>${title}</h1><p>${description}</p></div>${badge?`<div class="header-badge">${badge}</div>`:''}</div>`;}
function panelHeader(title,ico,right=''){return `<div class="panel-header"><h2>${icon(ico)}${title}</h2>${right}</div>`;}
