function showIssue(i){openDialog(`<span class="severity-label ${i.severity}" style="display:inline-flex">${i.severity.toUpperCase()}</span><h2>${esc(i.title)}</h2><p>${esc(i.description)}</p><h3>OBSERVED EVIDENCE</h3><pre>${esc(i.evidence)}</pre><h3>RECOMMENDED FIX</h3><p>${esc(i.fix)}</p>${report.demo?'<p>이 항목은 학습용 샘플입니다. 실제 URL에 대한 취약점으로 판정한 결과가 아닙니다.</p>':''}`,'HEXLAB / VULNERABILITY DETAIL');}
function download(data,name,type='application/json'){const a=document.createElement('a');const u=URL.createObjectURL(new Blob([data],{type}));a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function downloadReport(){download(JSON.stringify(report,null,2),'hexlab-report.json');toast('분석 리포트를 다운로드했습니다.');}
async function api(path,data){try{const res=await fetch(apiBase+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(60000)});const result=await res.json();if(!res.ok)throw new Error(result.error||'요청을 처리할 수 없습니다.');return result;}catch(e){if(e instanceof TypeError)throw new Error('분석 서버에 연결할 수 없습니다. 잠시 후 다시 시도하세요.');throw e;}}
async function runScan(value){const form=$('#scan-form');const btn=$('#scan-button');if(!form)return;form.classList.add('scanning');btn.disabled=true;btn.textContent='ANALYZING...';$('#scan-error').style.display='none';try{const data=await api('/api/scan',{url:value});report=data;issueFilter='all';historyReports.unshift(data);historyReports=historyReports.slice(0,12);try{localStorage.setItem('hexlab-reports',JSON.stringify(historyReports));}catch{}markMission('scan');$('#report-count').textContent=String(historyReports.length).padStart(2,'0');if(page==='scan')renderResults();toast('공개 응답에 대한 보안 분석을 완료했습니다.');return data;}catch(e){if($('#scan-error')){$('#scan-error').textContent=e.message;$('#scan-error').style.display='block';}return{error:e.message};}finally{form.classList.remove('scanning');btn.disabled=false;btn.innerHTML=`${icon('scan')}보안 분석 시작${icon('arrow')}`;}}
function markMission(name){$('#mission-'+name).checked=true;saveMissions();}
function saveMissions(){const values=['scan','edit','av'].map(s=>$('#mission-'+s).checked);try{localStorage.setItem('hexlab-missions',JSON.stringify(values));}catch{}$('#mission-progress').style.width=values.filter(Boolean).length/3*100+'%';$('#mission-caption').textContent=values.filter(Boolean).length+' / 3 COMPLETE';}
try{JSON.parse(localStorage.getItem('hexlab-missions')||'[]').forEach((v,i)=>{if(['scan','edit','av'][i])$('#mission-'+['scan','edit','av'][i]).checked=!!v;});}catch{}document.querySelectorAll('.sidebar-mission input').forEach(i=>i.onchange=saveMissions);saveMissions();
let disposeTypingBoard=()=>{},disposeIntroMotion=()=>{};
function navigate(route,push=true){disposeIntroMotion();disposeIntroMotion=()=>{};disposeTypingBoard();disposeTypingBoard=()=>{};window.scrollTo({top:0,behavior:'instant'});page=route;if(push)history.pushState({},'','#/'+(route==='intro'?'':route==='lab'?'lab/'+labMode:route));document.body.classList.toggle('intro-mode',route==='intro');document.body.classList.toggle('code-mode',route==='code');document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===route));$('#lab-subnav').hidden=route!=='lab';$('#breadcrumb-page').textContent=route==='intro'?'ACCESS TERMINAL':route==='lab'?'SIMULATION LAB':route==='code'?'CODE TERMINAL':'SECURITY SCAN';$('#sidebar').classList.remove('open');if(route==='lab')renderLab();else if(route==='intro')renderIntro();else if(route==='code')renderTypingPage();else renderScan();backgroundMusic.setPage(route,labMode);}
function routeFromLocation(){const path=location.hash?location.hash.slice(1):location.pathname;if(/\/lab\/bio(?:\/|$)/.test(path))labMode='bio';else if(/\/lab\/web(?:\/|$)/.test(path))labMode='web';return /\/lab(?:\/|$)/.test(path)?'lab':/\/scan(?:\/|$)/.test(path)?'scan':/\/code(?:\/|$)/.test(path)?'code':'intro';}
