function renderCodeRain(){
 const alphabet='01ABCDEF0123456789{}[]<>/\\=+*:#';
 const streams=Array.from({length:44},(_,column)=>{
  const length=18+Math.floor(Math.random()*20);
  const glyphs=Array.from({length},()=>alphabet[Math.floor(Math.random()*alphabet.length)]);
  const duration=9+Math.random()*10;
  return `<span class="code-rain-stream" style="--column:${column};--fall-duration:${duration.toFixed(2)}s;--fall-delay:${(-Math.random()*duration).toFixed(2)}s">${esc(glyphs.slice(0,-1).join('\n'))}\n<b>${esc(glyphs.at(-1))}</b></span>`;
 }).join('');
 return `<div class="intro-code-rain" aria-hidden="true">${streams}</div>`;
}
